// Forward-only, versioned migrations, generated by drizzle-kit from src/db/schema (drizzle/)
// and applied here: each runs once, in a transaction, recorded in schema_migrations with a
// checksum, under an advisory lock. Destructive statements are refused unless the file is
// explicitly marked as reviewed.
//
// Databases created before Drizzle (Phase 0A) carry the legacy migrations instead; for them
// the runner finishes any missing legacy files and records the Drizzle baseline as applied.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';
import type pg from 'pg';
import { syncRbacCatalogue } from '../rbac';

const API_DIR = fileURLToPath(new URL('../..', import.meta.url));
export const DRIZZLE_DIR = path.join(API_DIR, 'drizzle');
export const LEGACY_DIR = path.join(API_DIR, 'migrations', 'legacy');
const BASELINE_ID = 'drizzle:0000_baseline';
const LOCK_KEY = 4242001; // pg_advisory_lock key so two deploys can't migrate at once
const DESTRUCTIVE = /\b(DROP\s+(TABLE|SCHEMA|DATABASE|COLUMN|TYPE)|TRUNCATE)\b/i;
const ALLOW_DESTRUCTIVE = '-- acadex:reviewed-destructive';

export interface Migration {
  id: string;
  statements: string[];
  sql: string;
  checksum: string;
}

const read = (file: string) => fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n'); // same hash on every OS
const checksum = (sql: string) => crypto.createHash('sha256').update(sql).digest('hex');

export function loadLegacyMigrations(dir = LEGACY_DIR): Migration[] {
  return fs
    .readdirSync(dir)
    .filter((f) => /^\d{4}_[\w-]+\.sql$/.test(f))
    .sort()
    .map((file) => {
      const sql = read(path.join(dir, file));
      return { id: file.replace(/\.sql$/, ''), sql, statements: [sql], checksum: checksum(sql) };
    });
}

export function loadDrizzleMigrations(dir = DRIZZLE_DIR): Migration[] {
  const journal = JSON.parse(read(path.join(dir, 'meta', '_journal.json'))) as { entries: { idx: number; tag: string }[] };
  return [...journal.entries]
    .sort((a, b) => a.idx - b.idx)
    .map(({ tag }) => {
      const sql = read(path.join(dir, `${tag}.sql`));
      const statements = sql
        .split('--> statement-breakpoint')
        .map((s) => s.trim())
        .filter(Boolean);
      return { id: `drizzle:${tag}`, sql, statements, checksum: checksum(sql) };
    });
}

export async function migrate(pool: pg.Pool, { log = console.log }: { log?: (msg: string) => void } = {}) {
  const client = await pool.connect();
  try {
    await client.query('SELECT pg_advisory_lock($1)', [LOCK_KEY]);
    // migrations and reference-data sync work across all tenants
    await client.query("SET app.bypass_rls = 'on'");
    await client.query(`CREATE TABLE IF NOT EXISTS schema_migrations (
      id         TEXT PRIMARY KEY,
      checksum   TEXT NOT NULL,
      applied_at TIMESTAMPTZ NOT NULL DEFAULT now()
    )`);
    const applied = new Map<string, string>(
      (await client.query<{ id: string; checksum: string }>('SELECT id, checksum FROM schema_migrations')).rows.map(
        (r) => [r.id, r.checksum]
      )
    );

    const legacy = loadLegacyMigrations();
    const drizzle = loadDrizzleMigrations();
    const ran: string[] = [];

    const run = async (m: Migration) => {
      if (applied.has(m.id)) {
        if (applied.get(m.id) !== m.checksum) {
          throw new Error(`Migration ${m.id} was edited after it was applied. Add a new migration instead.`);
        }
        return;
      }
      if (DESTRUCTIVE.test(m.sql) && !m.sql.includes(ALLOW_DESTRUCTIVE)) {
        throw new Error(`Migration ${m.id} contains DROP/TRUNCATE. Review it and add "${ALLOW_DESTRUCTIVE}" if intended.`);
      }
      await client.query('BEGIN');
      try {
        for (const statement of m.statements) await client.query(statement);
        await client.query('INSERT INTO schema_migrations (id, checksum) VALUES ($1,$2)', [m.id, m.checksum]);
        await client.query('COMMIT');
      } catch (e) {
        await client.query('ROLLBACK');
        throw new Error(`Migration ${m.id} failed: ${(e as Error).message}`);
      }
      applied.set(m.id, m.checksum);
      log(`  applied ${m.id}`);
      ran.push(m.id);
    };

    // A pre-Drizzle database: has legacy records, or the original tables with no records at all.
    const hasLegacyRecords = legacy.some((m) => applied.has(m.id));
    const hasUntrackedTables =
      applied.size === 0 && (await client.query(`SELECT to_regclass('public.schools') AS t`)).rows[0]?.t !== null;
    if (hasLegacyRecords || hasUntrackedTables) {
      for (const m of legacy) await run(m);
      const baseline = drizzle[0];
      if (baseline && baseline.id === BASELINE_ID && !applied.has(baseline.id)) {
        await client.query('INSERT INTO schema_migrations (id, checksum) VALUES ($1,$2)', [baseline.id, baseline.checksum]);
        applied.set(baseline.id, baseline.checksum);
        log(`  recorded ${baseline.id} (existing database already has this schema)`);
        ran.push(baseline.id);
      }
    }

    for (const m of drizzle) await run(m);

    // reference data that must match the code: permission catalogue + built-in roles
    await syncRbacCatalogue(client);
    return ran;
  } finally {
    await client.query('SELECT pg_advisory_unlock($1)', [LOCK_KEY]).catch(() => {});
    client.release();
  }
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1]);
if (isMain) {
  const { pool } = await import('./pool');
  migrate(pool)
    .then((ran) => console.log(ran.length ? `✅ ${ran.length} migration(s) applied` : '✅ Database is up to date'))
    .catch((e: Error) => {
      console.error('❌ Migration failed:', e.message);
      process.exitCode = 1;
    })
    .finally(() => pool.end());
}
